class Solution {
public:
    int maxSatisfaction(vector<int>& satisfaction) {
        sort(satisfaction.begin(), satisfaction.end());
        long long total = 0, sum = 0, best = 0;
        for (int i = (int)satisfaction.size() - 1; i >= 0; i--) {
            sum += satisfaction[i];
            total += sum;
            if (total > best) best = total;
        }
        return (int)best;
    }
};
